/* 挑出最大那只碗，把它的门牌号挂到外面那张牌上 */
void pick_biggest(int *bowls, int n, int **out) {
    int best = 0;
    for (int i = 1; i < n; i++) {
        if (bowls[i] > bowls[best]) {
            best = i;
        }
    }
    *out = &bowls[best];
}

int main(void) {
    int bowls[3] = {{row}};
    int *p = &bowls[0];

    pick_biggest(bowls, 3, &p);
